import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const judgmentPhysicalScenarios=['judgment-jill-ordinary','judgment-jill-dedicated','judgment-uonos-ordinary','judgment-uonos-dedicated','judgment-jill-ordinary-counter','judgment-jill-dedicated-counter','judgment-uonos-ordinary-counter','judgment-uonos-dedicated-counter'] as const;
export type JudgmentPhysicalScenario=typeof judgmentPhysicalScenarios[number];
export function isJudgmentPhysicalScenario(name:string):name is JudgmentPhysicalScenario{return (judgmentPhysicalScenarios as readonly string[]).includes(name);}
export function judgmentPhysicalMode(name:JudgmentPhysicalScenario){const dedicated=name.includes('-dedicated'),counter=name.endsWith('-counter');return{card:'a2-p14-r2c3',dedicated,counter,owner:name.includes('-uonos-')?'邪祭ウーノス':'大神官ジル',effect:dedicated?9:8,damage:dedicated?20:16};}
export function makeJudgmentPhysicalScenario(name:JudgmentPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;follower?:'none';defense?:'evade'}={}){
 const m=judgmentPhysicalMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[options.owner??m.owner,'魔導王ガイナス','白魔術師シェリム','侍大将のシン'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+6-gameStats(s,p.id).spirit;}s.players[a]!.permanent!.magic_level=20+(options.level??8)-gameStats(s,a).magic_level;
 const metal=options.follower?null:takeCard(s,b,'メタルゴーレム'),soldier=options.follower?null:takeCard(s,b,'兵士'),guardian=options.follower?null:takeCard(s,c,'守護者'),keep=[takeCard(s,a,m.card),takeCard(s,b,'必勝の祈り'),takeCard(s,b,'a2-p15-r3c2'),takeCard(s,b,options.defense==='evade'?'a2-p05-r3c1':'a2-p06-r1c1'),takeCard(s,d,'命運凶変'),...[metal,soldier,guardian].filter((x):x is string=>!!x)];for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`JUDGMENT_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('JUDGMENT_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('JUDGMENT_IDS');}
 for(const p of players){for(const cardInstanceId of (p.id===b?[metal,soldier]:p.id===c?[guardian]:[]).filter((x):x is string=>!!x))act(p.id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});act(p.id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return s;
}
